use std::{fs,time::Instant,hint::black_box};
fn main(){let a:Vec<String>=std::env::args().collect();let data=fs::read(&a[1]).unwrap();assert_eq!(&data[..4],b"VQC1");let int=|o|u32::from_le_bytes(data[o..o+4].try_into().unwrap()) as usize;let rows=int(4);let width=int(8);let start=28+rows*16;let columns:Vec<Vec<f64>>=(0..rows).map(|r|(0..width).map(|i|{let o=start+(r*width+i)*8;f64::from_le_bytes(data[o..o+8].try_into().unwrap())}).collect()).collect();
let run=|fused:bool|{let now=Instant::now();for _ in 0..200{let c=black_box(&columns);let scales:Vec<f64>=if fused {c.iter().map(|c|c.iter().try_fold(0f64,|s,&v|if v.is_finite(){Ok(s.max(v.abs()))}else{Err(())})).collect::<Result<_,_>>().unwrap()}else {assert!(!c.iter().any(|c|c.iter().any(|v|!v.is_finite())));c.iter().map(|c|c.iter().map(|v|v.abs()).fold(0.,f64::max)).collect()};black_box(scales);}now.elapsed().as_secs_f64()};let _=run(false);let _=run(true);for pair in 0..7{let (b,c)=if pair%2==0{let b=run(false);(b,run(true))}else{let c=run(true);(run(false),c)};println!("{{\"pair\":{pair},\"baseline_s\":{b},\"fused_s\":{c}}}");}}
